"""Embedded custom assets for guaranteed inclusion in serverless bundles."""
from __future__ import annotations
import base64

_ASSETS = {
    "maker-chen-meilin": {
        "b64": "",
        "checksum": "12b03e28ec28111d33bafd989b2697ad4bfbb6a62c67133f0d233bd05a9a417d",
        "ratio": "tall",
        "alt_text": "Chen Meilin, Ceramicist",
        "content_type": "image/jpeg",
        "width": 750,
        "height": 1000,
        "byte_size": 99726,
    },
    "maker-lu-wenjing": {
        "b64": "",
        "checksum": "2640249bf06a46b70d3f3aa94080d57ae2c7807fc134a8e3a92e9b57530ed879",
        "ratio": "tall",
        "alt_text": "Lu Wenjing, Weaver & natural dyer",
        "content_type": "image/jpeg",
        "width": 750,
        "height": 1000,
        "byte_size": 140882,
    },
}

_DECODED_CACHE: dict[str, bytes] = {}

def get_asset_bytes(name: str) -> bytes | None:
    if name not in _ASSETS:
        return None
    if name not in _DECODED_CACHE:
        _DECODED_CACHE[name] = base64.b64decode(_ASSETS[name]["b64"])
    return _DECODED_CACHE[name]

def get_asset_meta(name: str) -> dict | None:
    return _ASSETS.get(name)
